 "content": "from collections import deque


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 8 and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        q.append((nr,nc))
            colored = [(rr,cc) for rr,cc in cells if grid[rr][cc] not in (0,8)]
            if not colored:
                continue
            r0, r1 = min(x[0] for x in colored), max(x[0] for x in colored)
            c0, c1 = min(x[1] for x in colored), max(x[1] for x in colored)
            ph, pw = r1-r0+1, c1-c0+1
            pattern = [[grid[r0+i][c0+j] for j in range(pw)] for i in range(ph)]
            for rr,cc in cells:
                out[rr][cc] = pattern[(rr-r0)%ph][(cc-c0)%pw]
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
